SELECT "lesson_id","module_id","title","description","content","duration","order_index","created_at","updated_at" FROM json_populate_recordset(NULL::public.lessons, '[{"lesson_id":"01c898c2-5e5d-4e5a-97fa-330be9d2d46f","module_id":"ee100c09-ed32-41bf-9d6e-7db5647fdf04","title":"Environmental Monitoring, Risk and Engineering Decisions","description":null,"content":"Choose monitoring objectives and stations, and distinguish access readiness from actual sampling. Identify hazards, exposure and risk priorities. Compare engineering options against evidence, cost and authority limits. Separate planned costs, conditional approvals, commitments, payments and closure decisions.","duration":"30 minutes","order_index":1,"created_at":"2026-11-18T06:03:15.362388+00:00","updated_at":"2026-11-18T06:03:15.362388+00:00"},{"lesson_id":"52f1a61a-b4d8-4849-85f8-478b38db8dbd","module_id":"34144afd-427e-4306-a792-d52fb063b79a","title":"Fluid Mechanics and River Hydraulics","description":null,"content":"Calculate river discharge from area and velocity. Explore the effect of a smaller pipe on flow speed, and learn how pressure, head and pump efficiency relate. Use Reynolds number to distinguish flow conditions. Interpret each result with its assumptions.","duration":"30 minutes","order_index":1,"created_at":"2026-11-18T06:03:15.362388+00:00","updated_at":"2026-11-18T06:03:15.362388+00:00"}]'::json)
